          '法典像一部清单：作伪证者承担所控之罪的刑罚；医生手术失败，按病人等级赔罚；工匠盖的房子塌了压死屋主，工匠偿命；出租的牛耕地时受了伤，责任如何分摊——从司法程序、租佃、婚姻，到债务与奴隶买卖，社会生活的每个角落都有条款接住，量刑精确到一舍克勒银子。',
