          '它也是一面镜子：二百八十二条里，自由民、平民、奴隶分属不同价目表，赔偿随身份浮动，一个人的法律身价明明白白写在条文里。后世读它，既读到秩序的起源，也读到偏见的起源——法典从诞生之日起就在回答「法律为谁服务」这个尖锐问题，而这个问题，到今天也没有过时。',
