          '画里有多少东西？后人清点：人物八百余、大小船只二十余艘、楼宇房屋三十余栋、牛马骡驴六十余头，还有骆驼队、轿子、独轮车与数不清的招幌。北宋东京常住人口超过百万，是当时世界上最大的城市；这幅画等于给一座百万人口的大都会做了一次全息存档。',
          '文字的对照版几乎同时存在：孟元老在北宋亡后写《东京梦华录》追忆汴京，写「八荒争凑，万国咸通」，写夜市至三更、早市又开张，写州桥夜市的灯火香气。画与书互为注脚——一图一文，从眼睛和耳朵两个方向，把一座已经消失的城市钉进了历史。',
