          '技法上是宋代写实主义的顶点。楼阁用界画尺规起稿，线条一丝不苟；船只的钉板、船舵、绞盘都交代得分明，后世造船史学者靠它复原汴河漕船的形制。八百多个人物几乎没有两个姿态重复——这是一座城市被一只极其冷静的眼睛看过一遍的证据。',
