          '历史给出了最残酷的注脚：画成后不到三十年，靖康之变，金军攻破汴京，徽钦二帝被掳北上，城中府库图籍焚掠一空。画里所有松懈的地方，后来都成了城破的入口；画里所有的热闹，都成了再也无法重返的日常——这就是为什么有人说，这幅画是汴京唯一的一张遗像。',
