          '「清明上河图」其实早已成为一种画题：明代仇英本画的是苏州，清代宫廷五画家合绘的清院本画的是想象中的盛世，存世各版本数以十计。真本 1950 年代回归故宫后极少露面——绢本脆弱，每展一次就要休眠数年。2015 年故宫「石渠宝笈」特展，观众排队六小时看十分钟，「故宫跑」从此成为热词。',
