          '随后是漫长的清点：五千余件文物逐件登记、拍照、搬运，卡特一个人干了将近十年才收尾；埃及政府与发掘方的文物归属之争随之而起，最终大部分珍藏留在埃及。1970 年代「图坦卡蒙宝物」世界巡展，所到城市动辄百万人排队——法老热从此席卷全球。',
          '「法老的诅咒」是另一条传播线：开墓数月后，卡纳冯死于蚊虫叮咬感染的败血症，小报把一连串巧合写成咒杀，所谓墓中死亡警告的铭文其实并不存在；后来有研究者统计当年在场者的寿命，与常人无异。诅咒是假的，但它把面具推成了流行文化巨星。',
