          '八个字的来历写在《史记·天官书》里：「五星分天之中，积于东方，中国大利；蛮夷大败。」五星指金木水火土五大行星，共现于东方天际，被占星家解读为利于中原王朝用兵的天象。一句朝廷的星占吉利话，被织进锦里、系上手臂、随葬地下——天文、纺织、政治在方寸之间交汇。',
