          '出土后它迅速成为国宝级明星：2002 年列入首批禁止出国（境）展览文物目录，从此再不出国门一步；它是新疆维吾尔自治区博物馆的镇馆之宝，展柜前常年围着最长的人群。2021 年，以它为题材的舞剧《五星出东方》搬上舞台并获文华大奖——一件文物，进入了当代艺术的谱系。',
          '斯坦因时代的文物流散与今天的联合发掘构成一组刺眼的对照：同一个尼雅，二十世纪初的规则是「谁挖到归谁」，成箱的木简与织物远走他乡；世纪末的规则改成了合作与共享。这方锦片能留在它出土的土地上，本身就是二十世纪考古伦理进步的一件物证。',
