      '537 年 12 月 27 日，君士坦丁堡。查士丁尼皇帝走进刚刚落成的大教堂，仰望那面直径 31 米、悬在半空的金色穹顶，说出一句流传千年的话：所罗门，我已超越了你！他要超越的不止是耶路撒冷圣殿，还有当时的物理认知——没有人说得清，那么大的穹顶凭什么能停在天上。近一千五百年后，工程师们仍在研究这个问题的答案。',
