          '雕版适合汉字：一部佛经刻一次版，可印千份，成本低廉。它与科举、历书一起，构成唐宋信息爆炸的三台引擎——政府靠它统一颁历，寺院靠它传播经典，书坊靠它卖考卷与蒙书。印刷术第一次证明：文字可以像农产品一样量产。',
