          '波特兰海图则是另一种务实：羊皮上画出地中海与黑海的海岸线，从中心放射出十六或三十二条罗盘方位线，港口、暗礁、锚地逐点标注。它不追求地理学意义上的正确投影，只回答水手的两个问题：航向几度，距离几里。现存最早的波特兰海图《比萨图》约成图于 1290 年，至今藏在法国国家图书馆。',
