          '细节开始说话。眉弓处铸有一条展翼的龙，双翼顺着眉线延伸，鼻梁上盘着蛇形饰——而当观者退后一步看整张面罩，龙与蛇的线条又拼出一张威严的人脸。一件头盔，两种图像：凑近是神话，退后是王的容颜。这种双重设计在盎格鲁-撒克逊与瑞典工艺中一脉相承，萨顿胡头盔与瑞典文德尔船墓的头盔几乎是同一套工艺的南北两版。',
