          '这直接改写了「黑暗时代」的教科书叙事。过去认为罗马军团撤离后，不列颠坠入文化真空，与地中海世界断联；萨顿胡的船舱证明：公元 600 年的英格兰王家，正坐在北欧、法兰克与拜占庭贸易网络的节点上，消费着、也生产着跨海文化。',
          '黑暗不是消失，是史料稀缺。船舱里的每一件东西，都在替沉默的档案发言。',
