          '萨顿胡还顺手解决了一个文学悬案。《贝奥武甫》——古英语最伟大的史诗——在 1939 年前被多数文学史家视为北欧传说的层累想象：船葬、金厅、跨海武士，像童话的布景。而萨顿胡的土丘下，船葬是真的，跨海贸易是真的，头盔与锁子甲是真的，甚至史诗开头丹麦王斯奇尔德的葬礼，正是躺在一艘满载珍宝的船上出海。',
          '学界由此重估这部诗：它可能保存着真实的 6 至 8 世纪武士社会的记忆——组织、器物、葬俗、价值观。文学的想象有边界，边界之外就是田野考古。一件头盔，让一首诗拿到了史料资格。',
