      '计算时代有两份出生证明。一份是 1946 年宾夕法尼亚大学公开的那台机器：约一万八千只电子管、27 吨重、占地 170 平方米，为算炮弹弹道而生——它比任何机械计算机快一千倍。另一份是次年贴进工作日志的一只真飞蛾：工程师在旁边写下「发现第一个真正的 bug」。文明从此多了一种新的失败方式，叫程序错误；也多了一群新的职业，叫找虫子的人。',
