          '技术上，ENIAC 还差最后一步：程序仍靠外部设置，机器本身不存程序。1945 年冯·诺伊曼加入后续设计，「存储程序」概念确立——同一台机器，换一套程序就能换一份工作。「通用」二字，自此才名副其实。',
