          '这个玩笑有它的语言史前提：「bug」作为机械故障的俚语早就在工程师圈子里流传，爱迪生 1878 年的信里就用它抱怨过自己的发明总出毛病。1947 年这只蛾子的意义在于把双关坐实了——从此「bug」专指程序与系统的错误，而排查错误的动作有了专属动词：debug，除虫。',
          '那页日志现藏史密森尼国家美国历史博物馆。计算时代的「创世神话」保存完好，主角是一只昆虫——技术史里最体面的幽默之一。',
