          '但比数字更深刻的是分工的变化：ENIAC 时代，人是机器的接线员；今天，机器是所有人的工具。「计算」从军用弹道表里的一道工序，变成了银行、医院、社交与出行的基础设施——1946 年那台机器的每一块短板，都长成了后来的一整个行业。',
