          '它的神话也值得记下：一台为战争而生的机器，孕育了最和平的应用；六位被当作「展品」的女性，实为第一代程序员；而「错误」被命名为一只小虫，被钉进日志永世流传。技术史的温情，常藏在这类细节里。',
          '从 ENIAC 到今天手机里的芯片，一直有个问题没变过：下一只 bug 在哪？只要这个问题还有人问，1947 年 9 月 9 日那只蛾子，就还活着。',
