          '第三个功能最常被忽略：长城是经济闸门。关隘平时是税口与互市场所，中原的粮、布、铁器与草原的马、皮、畜产品在此交易——墙内墙外的战争史之外，还有一部更长的市场史。明代大同、张家口的马市，就是关墙「开门营业」的样板。',
          '有趣的是注销它的恰恰是清朝：满洲出身的统治者既握草原又握中原，康熙帝直言「守国之道惟在修德安民」，以盟旗制度与木兰秋狝替代边墙，长城从此退役。军事设施的生命周期，取决于帝国的政治结构，而不取决于砖石是否结实。',
