          '它的源头更早：约前 2100 年起，苏美尔语已流传着五首独立的吉尔伽美什诗篇。主人公有历史原型——据苏美尔王表，乌鲁克王吉尔伽美什约生活于前 2700 年，王表记他在位一百二十六年，分明已开始神话化。一个真实的城邦王，用六百年长成了文学人物。',
