          '证据链相当可观。其一，西拿基立的铭文详述他在尼尼微修建的大型水利园林：引水渠、堤坝，甚至「以失蜡法铸造的青铜柱，用来提水浇灌高台上的草木」——青铜螺旋提水器，与斯特拉波描述的装置几乎对号。其二，尼尼微宫殿浮雕上确凿画着皇家花园的宴饮场景——亚述造园有图像实证。其三，希腊人常把美索不达米亚的大城混称为「巴比伦」，希罗多德就把亚述的故事安在巴比伦头上；名号漂移，在现代之前是常态。',
