          '而真实的造园传统有据可查：两河的水利技术、亚述的皇家猎苑与浮雕花园、新巴比伦城的仪典大道与伊什塔尔门——把野山水引入人工世界的工程能力，巴比伦与尼尼微都不缺。悬着的只是一次「归属登记」，不是一段文明。',
