    summary: '高棉帝国留下的最大宗教建筑，现存最大的宗教纪念物。',
    paragraphs: [
      '每年春分前后的清晨，太阳会从吴哥窟中央塔尖的正上方升起——五座塔的排列与太阳轨迹暗合，像一座用石头校准的宇宙钟。12世纪的高棉人没有望远镜，却把须弥山、四海与诸天搬到了这片平原上：护城河是咸海，三层回廊是山峦，中央塔是世界的轴心。走进吴哥窟，等于走进一座可以行走的宇宙模型。',
    ],
    sections: [
      {
        heading: '它是什么：献给毗湿奴的国家神庙',
        paragraphs: [
          '吴哥窟约建于1113—1150年，建造者是高棉国王苏利耶跋摩二世。它不同于寻常神庙：坐东朝西，入口面向日落——学者推测这是一座陵庙，主神是维护宇宙的毗湿奴。国王自称其化身，把王权、太阳与神殿焊在一处：拜这座庙，就是拜这个王朝。',
          '它的规模至今无人超越：外围占地约162公顷，护城河宽近200米，是地球上现存最大的宗教建筑群。支撑奇迹的不是神迹，而是水——吴哥王朝用运河与巨型蓄水池驯服季风，灌溉出供养大量人口的水稻平原，才有余力把一个国家的力气砌进石头。',
        ],
      },
      {
        heading: '工艺：四十公里外的砂山与八百米浮雕',
        paragraphs: [
          '石料来自约40公里外的荔枝山——高棉人的圣山。据近年勘测，工匠挖了运河，用木筏与水闸把成千上万块砂岩顺水送到工地，再用大象与坡道拉上塔顶。整座庙不用灰浆，靠石块咬合与自重压紧，八百年风雨与数次地震没能推倒主塔。',
          '第一层回廊的浮雕绵延约800米，是世界上最长的连续浮雕带：《摩诃婆罗多》的大战、《罗摩衍那》的救援、搅拌乳海创世的神话，与高棉军阵、市集、厨房排在同一面墙上——众神与炊烟共处一壁。浮雕里苏利耶跋摩二世的形象比神还大，站在伞盖下接受朝拜。',
        ],
      },
      {
        heading: '功能与主人：从王陵到佛寺',
        paragraphs: [
          '国王死后，庙的职能转向祭祖与陵寝；14世纪以后，吴哥窟渐渐变成上座部佛寺，延续至今——它因此是世界上少数「一直在使用」的千年古迹。今天柬埔寨人出家、办婚礼仍来此绕塔，僧袍的橙色映在灰砂岩上。',
          '1296年，元朝使团随员周达观在吴哥住了一年，回国写下《真腊风土记》，记下这座都城的城门、宫室与市井——彼时城外万顷稻田，漕船往来。这份报告成了近代世界重新认识吴哥的一把钥匙：欧洲人要再等五百年，才知道这里曾有过怎样一座都城。',
        ],
      },
      {
        heading: '流传：从帝都到丛林，再到旗帜',
        paragraphs: [
          '1431年，暹罗大军攻陷吴哥，高棉朝廷迁往金边一带，都城人口散尽，神庙退回丛林。但它从未「失踪」：周边村落的僧人与农民一直守着它。欧洲人要等到1860年——博物学家穆奥循着传闻进山，把「丛林里的巨大庙宇」写成游记，轰动了世界。',
          '20世纪的战争带来新的劫难：内战与红色高棉时期，吴哥文物被成批盗凿流失。1992年吴哥列入世界遗产并同时进入濒危名单，三十多个国家接力修复，2004年才移出濒危名录。今天，吴哥窟印在柬埔寨国旗正中——一个国家的名字与记忆，钉在一座庙上。',
        ],
      },
      {
        heading: '意义：用水与石头写的长程遗产',
        paragraphs: [
          '吴哥的兴衰是一部水利史：灌溉网养活了帝国，也可能拖垮了帝国——据研究，14—15世纪的季风异常与水利系统淤塞，或是王朝弃城的推手。最先进的工程与最深的神学在同一场溃败里落幕，只剩石头的宇宙模型原地不动。',
          '今天每年数百万人从世界各地来看日出：他们举起的手机，对着的是九百年前就已算好的日出方位。一个王朝的政权早已消失，它对宇宙秩序的想象却仍在每个清晨重演一次——这是建筑战胜时间的少数例证之一。',
        ],
      },
    ],
