          '这一偏，反而最动人：他为一个人造了全世界最对称的建筑，自己却没能挤进对称里。帝国国库为这座陵墓掏空了余裕，此后莫卧儿由盛转衰——史家常把泰姬陵读作黄金时代的墓碑：它纪念一个死者，也埋葬了一个盛世。',
