    paragraphs: [
      '1871年，德国地质学家毛赫在津巴布韦高原的丛林里撞见一堵墙：11米高、五米多厚，全部用修凿过的花岗岩块干垒而成，不用一滴灰浆。他绕着墙走了几圈，拒绝相信眼前的一切属于非洲人——他认定这就是《圣经》里示巴女王的城。这个错误，统治欧洲学界半个世纪。',
    ],
    sections: [
      {
        heading: '它是什么：石头垒成的王都',
        paragraphs: [
          '大津巴布韦位于高原之上，建于约1100—1450年，是绍纳人王国的都城——「津巴布韦」在绍纳语里意即「石头房子」。全城分三片：山顶的王室居所、谷地的平民聚落，与最壮观的大围城：围墙周长逾250米，最高处11米，用石据估算逾万吨。',
          '据估算，全盛期城内外住着一万到一万八千人，是撒哈拉以南非洲当时最大的城市之一。城中立着一座实心的锥形塔，高约10米，用途至今没有定论——粮仓、王权象征或祭祀装置，一切解释都停在「据推测」。',
        ],
      },
      {
        heading: '工艺：不用灰浆的极致工程',
        paragraphs: [
          '石料就地取材：高原的花岗岩风化后成层剥落，工匠顺着纹理撬下石板，稍加修凿便层层干垒。不用灰浆的墙是「软」的，能跟着地震与热胀冷缩呼吸——八百年不倒。砌墙人还留下手工的弧度：围墙不取直线，而是随地形起伏的曲线，像给大地量体裁衣。',
          '财富的来源在地下与路上：高原金矿的沙金在此集散，运往约一千公里外的东非港口基尔瓦，换回波斯的陶器、印度的念珠与中国的瓷器——遗址里出土的中国瓷片就是铁证。1331年，摩洛哥旅行家伊本·白图泰到访基尔瓦，盛赞其为世界最美的城市之一——这条印度洋贸易链的一端，就拴在津巴布韦高原上。',
        ],
      },
      {
        heading: '功能与主人：山上的王，墙外的世界',
        paragraphs: [
          '王住在山丘城，透过石墙的窄缝俯瞰谷地；祭祀在山顶举行，贸易与农耕在山下展开。墙不只是防御，更是等级的可见化——能否走进大围城，本身就是身份。皂石雕成的「津巴布韦鸟」高踞石柱，是这片土地最著名的出土物：鹰身立于人形柱头，至今没有被完全读懂。',
          '15世纪后，因矿源枯竭与贸易线转移，王国渐渐衰落，权力中心北移，城市人去屋空，丛林合拢，只留下巨墙与皂石鸟给过路人猜测。等到欧洲人到来，看到的正是一座「无主」之城——于是，一个白人女王的故事被郑重其事地编了出来，还流行了一百年。',
        ],
      },
      {
        heading: '流传：殖民者的否认与科学的纠正',
        paragraphs: [
          '毛赫之后，殖民机构资助的考古长期宣称此城是腓尼基人或示巴女王所建，殖民地政府甚至向出版物施压，不许说它出自非洲人之手（据载有考古学者因坚持结论而丢掉差事）。1905年，考古学家兰德尔-麦克弗用年代学证明其属中世纪非洲；1929年，卡特·汤普森进一步确证：年代、工艺与葬俗全部指向本地传统。',
          '政治层面更荒诞：1965年白人政权单方面「独立」时，官方仍坚称非非洲人起源。1980年，新国家建国，干脆用这座城命名自己——津巴布韦。八只皂石鸟在19世纪末被掠往他处，其中一只2003年从德国追回，其余仍散落在外。',
        ],
      },
      {
        heading: '意义：被归还的名字',
        paragraphs: [
          '1986年大津巴布韦列入世界遗产。今天它是国民身份证：国旗正中是津巴布韦鸟，国名来自石城，货币、机场与街区都沿用此名，遗址的历史也被写进中小学生的课本。一座被殖民者否认过的废墟，成了后殖民国家最响亮的自我介绍。',
          '它的故事给考古学留下一条诫命：当证据与偏见冲突时，听证据的，哪怕证据属于被你看不起的人群。大津巴布韦用了近六十年、两代考古学家，才把结论扳回来；如今遗址门口的说明牌一字一句重述绍纳人的故事。石头不会说谎，说谎的从来是叙述石头的人。',
        ],
      },
    ],
    quote: '基尔瓦是世界上最优美、建造得最好的城市之一。',
