          '1912年清帝退位，末代皇帝溥仪仍按优待条件住在内廷，直到1924年被逐出。1925年，故宫博物院挂牌成立——皇帝的家，一夜之间变成国民的博物馆。从「紫禁」到「故宫」，一字之差，换了人间。至于乾清宫「正大光明」匾后藏传位诏书的传说，本属野史轶闻，却被后世反复演绎——这座城连退场的方式，都自带戏剧剧本。',
