          '1987年紫禁城列入世界遗产；2024年，「北京中轴线」申遗成功，紫禁城是这条文化廊道的核心节点。如今故宫年观众上千万人次，是全球参观人数最多的博物馆——五百年前为一个人建造的禁地，如今每天接纳一座中等县城的人口。',
