    foreign: 'Petra',
image: {
      src: 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Al_Deir_Petra.JPG/960px-Al_Deir_Petra.JPG',
      page: 'https://commons.wikimedia.org/wiki/File:Al_Deir_Petra.JPG',
      author: 'Azurfrog',
      license: 'CC BY-SA 3.0',
    },
    region: 'middle-east',
    year: -312,
    range: [-312, 106],
    kicker: '玫瑰色的沙漠之城',
    summary: '纳巴泰人在峡谷峭壁上凿出的商都，宝库门面高三十九米。',
    paragraphs: [
      '1812 年 8 月 22 日，约旦南部的峡谷里，一位化装成阿拉伯朝圣者的瑞士青年跟着贝都因向导拐进一条仅容一骑的窄缝。两壁岩崖高逾八十米，天光在头顶裂成一线；走到尽头，一座近四十米高的神殿立面从玫瑰色砂岩里「长」了出来——柱廊、雕像、檐口，像把整座山当成画布凿出来的。青年约翰·路德维希·布尔克哈特在日记里承认：他假装虔诚许愿献祭山羊，才敢在这座被西方遗忘了五百年的城市里多留几个小时。',
    ],
    sections: [
      {
        heading: '它是什么：峡谷尽头的都城',
        paragraphs: [
          '佩特拉是纳巴泰人的都城。纳巴泰是支阿拉伯裔的游牧商团，约前 4 世纪起定居于此；前 312 年，亚历山大部将安提柯的军队两次南下袭击，都被他们依托岩山击退——古希腊史家狄奥多鲁斯据此写下这个民族最早的清晰记载。「佩特拉」在希腊语里就是「岩石」。',
          '它藏在死海与亚喀巴湾之间的裂谷山地：唯一通途是那条 1.2 公里长的西克峡谷，两壁高八十到一百米，最窄处仅三四米。谷尽头的城中有神殿、王墓、剧场、列柱大道与神庙群，鼎盛时居民约两三万——一座完整的都会，全「装」在一条外人找不到的裂缝尽头。',
        ],
      },
      {
        heading: '工艺与细节：把山从上往下啃掉一半',
        paragraphs: [
          '纳巴泰工匠的凿法独一份：不打地基、不用脚手架，从崖顶往下分层开凿——先剥除外围岩体，再修整立面、掏出门窗，自上而下直到地面。宝库（卡兹尼）立面高约三十九米；罗马剧场依崖凿出，可容数千观众；王家陵墓沿崖排开成街。五百年间，几代工匠在同一道山崖上刻出了一座城。',
          '更见功力的是看不见的水利：此地年降水不足百毫米，纳巴泰人却把水做成了国力——谷口筑坝拦洪，崖壁凿出水窖，陶管引泉入城，蓄水足以供养数万人畜；据狄奥多鲁斯记载，他们甚至能引水灌进峡谷退敌。没有水就没有佩特拉；反过来，控制了水，就控制了整条商路。',
        ],
      },
      {
        heading: '功能与主人：香料之路上的收费站',
        paragraphs: [
          '佩特拉的财富来自位置：它卡在阿拉伯半岛乳香没药运往地中海的必经之路上——从阿曼与也门到加沙的香料之路绵延两千多公里，商队驮着乳香、没药与丝绸穿过沙漠，纳巴泰人在沿途设站、护航、收税，把「过路费」收成了一个王国。',
          '他们是沙漠里的技术官僚：商站、水窖与驿道铺满内盖夫沙漠，钱币与陶器自成一格；本地主神杜沙拉与希腊、埃及诸神在崖壁浮雕里混坐一龛——商路城市的神，从来都讲世界语。更久远的影响藏在笔画里：纳巴泰人使用的阿拉米变体字母，后来演变成阿拉伯字母——今天数亿人书写的文字，祖先刻在佩特拉的岩壁上。',
        ],
      },
      {
        heading: '流传命运：罗马、地震与五百年的遗忘',
        paragraphs: [
          '106 年，罗马皇帝图拉真吞并纳巴泰，设阿拉伯行省，佩特拉降为行省都市；贸易重心渐渐移向北方新贵帕尔米拉与红海航线，城市开始失血。363 年与 551 年两场大地震接连摧毁建筑与水网，拜占庭时代尚有主教座堂，阿拉伯征服后城市逐渐空置——沙漠收回了它借出去的一切。',
          '此后五百多年，除了贝都因人，几乎没人记得峡谷里藏着城。1812 年布尔克哈特重见天日，19 世纪的画家与旅行者蜂拥而至，1958 年起考古队系统发掘；1985 年列入世界遗产，2007 年又以全球票选跻身「新七大奇迹」。被遗忘了五百年的城，用一百年重新排进人类的名册。',
        ],
      },
      {
        heading: '意义：刻在石头上的商路文明',
        paragraphs: [
          '佩特拉常被当作「奇观」，它真正的身份是证据：一个没有大河、没有耕地的民族，靠水利工程与商业信用在沙漠里建成都会——它证明文明的燃料未必是农田，也可以是物流与契约。香料之路从也门到加沙的遗址链上，它是保存最完好的一环。',
          '1845 年，牛津学者柏根为它写下那句诗：「一座玫瑰红的城，有时光一半古老。」玫瑰色砂岩在夕阳里真的会发红。今天每天数千游客沿西克峡谷走进去，像当年的商队一样，在裂缝尽头撞见神殿——岩城不语，商路已远，水窖里偶尔还能存住一场雨。',
        ],
      },
    ],
    quote: '一座玫瑰红的城，有时光一半古老。',
