          '它是英国最著名的史前纪念碑，却直到 17 世纪才开始被认真丈量：詹姆斯一世曾派建筑师伊尼戈·琼斯前往考察，此后测绘与试掘不断。1950 年代的放射性碳测年第一次给出可靠时间轴——比罗马帝国早两千多年，与大金字塔的营造期相距不算太远。',
