    summary: '维苏威火山灰封存的罗马城市，日常生活被完整截取样本。',
    paragraphs: [
      '公元 79 年，维苏威山顶炸开的那朵云，形状像一棵伞松——先立起树干，再张开树冠。住在海湾另一头的小普林尼把它写进了给史家塔西佗的信里。火山脚下的庞贝，起初落的是石子雨，接着是数米厚的浮石，屋顶开始塌陷；第三天凌晨，滚烫的碎屑流沿山坡扑下，把一切停在原位。约两万人的城市，从此被火山灰真空包装了十七个世纪。',
    ],
    sections: [
      {
        heading: '它是什么：一座被「暂停」的罗马城',
        paragraphs: [
          '庞贝在维苏威山脚下、那不勒斯湾南岸：面包房、酒馆、浴场、露天剧场与角斗士营房俱全，是一座标准的罗马中等城市。城墙上竞选标语层层叠叠——「请投面包师某某一票」，选举海报与情话刻在同一面墙上，涂鸦逾万条。',
          '灾难在公元 79 年降临（一说实为 10 月，炭笔涂鸦与衣物证据支持秋季说，传统的「8 月 24 日」系对小普林尼文献的推定）。最初几小时，人们还在逃与留之间摇摆：有人收拾行李等风向，有人躲进地窖——多数遇难者最终倒在门洞与花园里，怀里抱着钱袋与家神像。',
        ],
      },
      {
        heading: '工艺与细节：灰烬里的肉身与面包',
        paragraphs: [
          '发掘者发现灰烬里的空腔——尸体腐尽后留下的形状。1863 年，考古学家菲奥雷利发明「石膏灌注法」：向空腔注入石膏，取出人形铸像——母子相拥、犬只蜷曲、以手掩面倒地的人。痛苦从此可被复制、可被展出，这也是庞贝至今未歇的展陈伦理之争：标本是科学，还是景观？',
          '细节之精确令人不安：出炉的碳化面包印着面包房的戳记，酒馆柜台的大瓮里验出酒渣，墙上用红字记着账目与骂人话；外科医生的作坊里，手术器械成套摆放。赫库兰尼姆的纸莎草卷被碳化成「化石卷轴」——今天用粒子加速器扫描，正一卷卷虚拟展开。',
        ],
      },
      {
        heading: '功能与主人：普通人的城市史',
        paragraphs: [
          '庞贝的价值不在帝王：它是普通罗马人一天的全比例模型。住屋有前店后宅的标准制式，富人别墅与穷人公寓只隔一条巷子；浴场的水管、面包房的石磨、酒馆的价目壁画——社会史、经济史、医疗史都能在这里找到实物证据。',
          '城市在死前正经历重建：17 年前的大地震震塌了半座城，居民修修补补住了回来，许多墙体还留着抢修的接缝。涂鸦里的抱怨、账本里的赊欠、门槛上的「当心恶犬」马赛克——一座城市的日常质感，连同它未完工的脚手架，被火山灰原样封存在数米浮石之下。',
        ],
      },
      {
        heading: '流传命运：从挖宝到科学发掘',
        paragraphs: [
          '1592 年，建筑师方塔纳挖灌溉渠时碰到壁画，庞贝重新进入视野；真正的大规模发掘始于 1748 年——那不勒斯王室把它当宝库。1808 年起有了地层记录，1863 年菲奥雷利确立科学方法；今天它是全世界持续发掘时间最长的遗址，约三分之一的城区刻意留着不挖——等更先进的技术。',
          '保护与流失同步：二战轰炸毁去一角，游客的呼吸与踩踏侵蚀壁画，2010 年角斗士营房坍塌震动世界，欧盟为此拨款上亿欧元抢修；近年的第五区发掘甚至开设直播，新出土的涂鸦逐条上网公布——一座两千年前的城市考古，成了全世界的公开课。',
        ],
      },
      {
        heading: '意义：灾难给未来的礼物',
        paragraphs: [
          '庞贝与图坦卡蒙墓、萨顿胡船葬同属一类证据：不是文字里的历史，而是生活本身的「时间切片」。帝王史看到的是诏书与战争，庞贝看到的是面包的重量、房租的数目、酒客的玩笑——历史学因此多了一个门类：日常生活史。',
          '它也定义了灾难考古的伦理边界：把受难者铸成展品是否恰当？庞贝用近三百年的争论回答：如实呈现，但拒绝猎奇——今天的展陈反复强调「他们和我们一样」。火山偷走了两万条生命，却把罗马人的清晨、账本与幽默，原样交给了未来。',
        ],
      },
    ],
