      '1957 年 1 月，悉尼，国际竞赛评审团翻到一份编号靠后的方案时停住了：几笔流动的白色曲线，画在一张不带比例尺的草图上。从落选堆里把它捡回来的评审沙里宁对同行说：先生们，这是第一名。画图的是位 38 岁的丹麦建筑师，当时连澳大利亚都没去过。方案被叫作「帆影」——此后十七年，这组白帆将把一座城市的预算、两届政府和一位天才建筑师，全都卷进湾流里。',
