          '信息密度才是它最惊人的地方：维京式船只的构造、锁子甲的穿法、骑枪的持法、木堡的形制，全有细节可考。历史学家用它复原黑斯廷斯战役，军事史家用它研究诺曼骑兵战术；有人数过，它绣了两百余匹马、数十只狗与鸟——中世纪的新闻片，帧率极低，信息量极大。',
