          '1982 年起，它陈列在巴约挂毯博物馆的恒温恒湿展廊。英法两国多次讨论「出借」——本世纪双方敲定将首次赴英展出，巴约居民抗议「嫁女儿」，反对签名的横幅挂满了市政厅外的街。九百年里它只离乡过一次半——去巴黎那次，算半次。',
